___CSS_LOADER_EXPORT___.push([module.id, `/* @conduction/nextcloud-vue — Dashboard component styles */

/* Dashboard page layout */
.cn-dashboard-page {
	padding: 20px;
	max-width: 1400px;
}

/* Widget grid item borders for non-tile widgets */
/* stylelint-disable-next-line selector-pseudo-class-no-unknown */
.cn-dashboard-grid :deep(.grid-stack-item-content:has(.cn-widget-wrapper)) {
	border: 1px solid var(--color-border);
}

/* Dashboard widget content area */
.cn-dashboard-widget-content {
	padding: 16px;
}

/* Dashboard KPI row inside grid */
.cn-dashboard-kpi-row {
	display: flex;
	align-items: center;
	gap: 12px;
	padding: 16px;
	height: 100%;
}

/* Dashboard chart container */
.cn-dashboard-chart {
	padding: 16px;
	height: 100%;
	display: flex;
	flex-direction: column;
}

.cn-dashboard-chart__title {
	margin: 0 0 12px;
	font-size: 15px;
	font-weight: 600;
}

.cn-dashboard-chart__content {
	flex: 1;
	min-height: 0;
	overflow: auto;
}

/* Dashboard list widget */
.cn-dashboard-list {
	padding: 0;
	margin: 0;
	list-style: none;
}

.cn-dashboard-list__item {
	display: flex;
	align-items: center;
	gap: 8px;
	padding: 8px 16px;
	cursor: pointer;
	border-bottom: 1px solid var(--color-border-dark);
}

.cn-dashboard-list__item:last-child {
	border-bottom: none;
}

.cn-dashboard-list__item:hover {
	background: var(--color-background-hover);
}
