.cn-widget-wrapper[data-v-f31f8c0c] {
	height: 100%;
	display: flex;
	flex-direction: column;
	background: var(--color-main-background);
	border: 1px solid var(--color-border);
	overflow: hidden;
}
.cn-widget-wrapper__content[data-v-f31f8c0c] {
	flex: 1;
	overflow: auto;
	min-height: 0;
	padding: 16px;
}
.cn-widget-wrapper--borderless[data-v-f31f8c0c] {
	border: none;
	background: transparent;
}
.cn-widget-wrapper--borderless .cn-widget-wrapper__content[data-v-f31f8c0c] {
	padding: 0;
}
.cn-widget-wrapper--flush .cn-widget-wrapper__content[data-v-f31f8c0c] {
	padding: 0;
}
.cn-widget-wrapper__header[data-v-f31f8c0c] {
	display: flex;
	align-items: center;
	justify-content: space-between;
	padding: 12px 16px;
	border-bottom: 1px solid var(--color-border);
	flex-shrink: 0;
}
.cn-widget-wrapper__header-left[data-v-f31f8c0c] {
	display: flex;
	align-items: center;
	gap: 8px;
	min-width: 0;
}
.cn-widget-wrapper__icon[data-v-f31f8c0c] {
	width: 24px;
	height: 24px;
	flex-shrink: 0;
}
.cn-widget-wrapper__title[data-v-f31f8c0c] {
	font-weight: 600;
	font-size: 14px;
	margin: 0;
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
}
.cn-widget-wrapper__title-meta[data-v-f31f8c0c] {
	display: flex;
	align-items: center;
	gap: 4px;
	font-size: 12px;
	color: var(--color-text-maxcontrast);
	white-space: nowrap;
	flex-shrink: 0;
}
.cn-widget-wrapper__actions[data-v-f31f8c0c] {
	display: flex;
	gap: 4px;
	flex-shrink: 0;
}
.cn-widget-wrapper__title-icon[data-v-f31f8c0c] {
	display: flex;
	align-items: center;
	flex-shrink: 0;
}
.cn-widget-wrapper__footer[data-v-f31f8c0c] {
	display: flex;
	justify-content: flex-end;
	gap: 8px;
	padding: 8px 16px;
	border-top: 1px solid var(--color-border);
	flex-shrink: 0;
}
.cn-widget-wrapper__footer-link[data-v-f31f8c0c] {
	font-size: 13px;
	color: var(--color-primary-element);
	text-decoration: none;
}
.cn-widget-wrapper__footer-link[data-v-f31f8c0c]:hover {
	text-decoration: underline;
}
