.cn-detail-page__header {
	display: flex;
	justify-content: space-between;
	align-items: center;
	margin-bottom: calc(4 * var(--default-grid-baseline));
	flex-wrap: wrap;
	gap: calc(4 * var(--default-grid-baseline));
