ss=\"cn-contacts-card__list\">\n\t\t\t<li\n\t\t\t\tv-for=\"item in displayedContacts\"\n\t\t\t\t:key=\"item.id\"\n\t\t\t\tclass=\"cn-contacts-card__item\">\n\t\t\t\t<NcAvatar\n\t\t\t\t\t:size=\"32\"\n\t\t\t\t\t:display-name=\"item.displayName || unknownLabel\"\n\t\t\t\t\t:user=\"avatarSeed(item)\"\n\t\t\t\t\t:url=\"item.avatarUrl || undefined\"\n\t\t\t\t\t:is-no-user=\"true\"\n\t\t\t\t\t:disable-menu=\"true\"\n\t\t\t\t\t:disable-tooltip=\"true\"\n\t\t\t\t\t:show-user-status=\"false\" />\n\t\t\t\t<div class=\"cn-contacts-card__item-text\">\n\t\t\t\t\t<span class=\"cn-contacts-card__item-name\">{{ item.displayName || unknownLabel }}</span>\n\t\t\t\t\t<span v-if=\"item.email\" class=\"cn-contacts-card__item-email\">{{ item.email }}</span>\n\t\t\t\t</div>\n\t\t\t\t<CnStatusBadge\n\t\t\t\t\tv-if=\"item.role\"\n\t\t\t\t\t:label=\"item.role\"\n\t\t\t\t\tvariant=\"default\"\n\t\t\t\t\tsize=\"small\" />\n\t\t\t</li>\n\t\t</ul>\n\n\t\t<footer v-if=\"contactsArray.length > displayMax\" class=\"cn-contacts-card__footer\">\n\t\t\t<button\n\t\t\t\ttype=\"button\"\n\t\t\t\tclass=\"cn-contacts-card__view-all\"\n\t\t\t\t@click=\"$emit('view-all')\">\n\t\t\t\t{{ viewAllLabel }} ({{ contactsArray.length }})\n\t\t\t</button>\n\t\t</footer>\n\t</div>\n</template>\n\n<script>\nimport { translate as t } from '@nextcloud/l10n'\nimport { NcAvatar, NcLoadingIcon } from '@nextcloud/vue'\nimport AccountMultiple from 'vue-material-design-icons/AccountMultiple.vue'\nimport AlertCircleOutline from 'vue-material-design-icons/AlertCircleOutline.vue'\n\nimport CnStatusBadge from '../../../components/CnStatusBadge/CnStatusBadge.vue'\nimport { buildHeaders } from '../../../utils/index.js'\n\n/**\n * CnContactsCard — vCard contacts widget.\n *\n * Renders four surfaces; the `single-entity` surface is the canonical\n * person chip used by every schema property typed\n * `referenceType: 'contacts'` across the app suite.\n *\n * Basic usage\n * ```vue\n * <CnContactsCard\n *   register=\"my-register\"\n *