rray.isArray(this.contacts) ? this.contacts : []\n\t\t},\n\n\t\t/**\n\t\t * Most recent N (sorted by `linkedAt` desc).\n\t\t */\n\t\tdisplayedContacts() {\n\t\t\tconst sorted = [...this.contactsArray].sort((a, b) => {\n\t\t\t\tconst aT = a?.linkedAt ? new Date(a.linkedAt).getTime() : 0\n\t\t\t\tconst bT = b?.linkedAt ? new Date(b.linkedAt).getTime() : 0\n\t\t\t\treturn bT - aT\n\t\t\t})\n\t\t\treturn sorted.slice(0, this.displayMax)\n\t\t},\n\n\t\t/**\n\t\t * For the single-entity chip: prefer the prop-supplied contact,\n\t\t * else the first fetched one.\n\t\t */\n\t\tprimaryContact() {\n\t\t\treturn this.contact || this.contactsArray[0] || null\n\t\t},\n\n\t\tchipTitle() {\n\t\t\tconst c = this.primaryContact\n\t\t\tif (!c) return ''\n\t\t\tconst bits = [c.displayName, c.email, c.role].filter(Boolean)\n\t\t\treturn bits.join(' — ')\n\t\t},\n\t},\n\n\twatch: {\n\t\tobjectId: {\n\t\t\timmediate: true,\n\t\t\thandler(id) {\n\t\t\t\t// In single-entity mode with a pre-resolved `contact`,\n\t\t\t\t// no fetch needed.\n\t\t\t\tif (this.surface === 'single-entity' && this.contact) {\n\t\t\t\t\treturn\n\t\t\t\t}\n\t\t\t\tif (id && this.register && this.schema) {\n\t\t\t\t\tthis.fetchContacts()\n\t\t\t\t}\n\t\t\t},\n\t\t},\n\t},\n\n\tmethods: {\n\t\tinitialsFor(contact) {\n\t\t\tconst name = (contact?.displayName || '').trim()\n\t\t\tif (name === '') return '?'\n\t\t\tconst parts = name.split(/\\s+/).filter(Boolean)\n\t\t\tif (parts.length === 1) return parts[0].charAt(0).toUpperCase()\n\t\t\treturn (parts[0].charAt(0) + parts[parts.length - 1].charAt(0)).toUpperCase()\n\t\t},\n\n\t\t/**\n\t\t * Stable seed for NcAvatar's deterministic colour + initials.\n\t\t *\n\t\t * @param {?object} contact ContactLink JSON (may be null).\n\t\t *\n\t\t * @return {string}\n\t\t */\n\t\tavatarSeed(contact) {\n\t\t\tif (!contact) return '?'\n\t\t\treturn contact.contactUid || contact.email || contact.displayName || '?'\n\t\t},\n\n\t\tasync fetchContacts() {\n\t\t\tif (!this.register || !this.schema || !this.objectId) return\n\t\t\tthis.loading = true\n\t\t\tthis.error = null\n\t\t\ttry {\n\t\t\t\tconst url = `${this.apiBase}/objects/${this.register}/${this.schema}/${this.objectId}/integrations/contacts`\n\t\t\t\tconst response = await fetch(url, { headers: buildHeaders() })\n\t\t\t\tif (!response.ok) {\n\t\t\t\t\tthis.error = `${response.status} ${response.statusText}`\n\t\t\t\t\tthis.contacts = []\n\t\t\t\t\treturn\n\t\t\t\t}\n\t\t\t\tconst data = await response.json()\n\t\t\t\tthis.contacts = this.unwrapList(data)\n\t\t\t} catch (err) {\n\t\t\t\tconsole.error('CnContactsCard: Failed to fetch contacts', err)\n\t\t\t\tthis.error = String(err?.message || err)\n\t\t\t\tthis.contacts = []\n\t\t\t} finally {\n\t\t\t\tthis.loading = false\n\t\t\t}\n\t\t},\n\n\t\t/**\n\t\t * Normalise a list-shaped response body to an array. See\n\t\t * CnContactsTab.unwrapList for the same canonical cascade\n\t\t * (results → items → bare array → []).\n\t\t *\n\t\t * @param {*} data parsed JSON response body\n\t\t *\n\t\t * @return {Array}\n\t\t */\n\t\tunwrapList(data) {\n\t\t\tif (Array.isArray(data)) {\n\t\t\t\treturn data\n\t\t\t}\n\t\t\tif (data && typeof data === 'object') {\n\t\t\t\tif (Array.isArray(data.results)) {\n\t\t\t\t\treturn data.results\n\t\t\t\t}\n\t\t\t\tif (Array.isArray(data.items)) {\n\t\t\t\t\treturn data.items\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn []\n\t\t},\n\t},\n}\n</script>\n\n<style scoped>\n.cn-contacts-card {\n\tdisplay: flex;\n\tflex-direction: column;\n\tgap: 8px;\n\tpadding: 8px;\n}\n\n.cn-contacts-card--chip {\n\tflex-direction: row;\n\talign-items: center;\n\tpadding: 4px 8px;\n\tbackground-color: var(--color-background-hover);\n\tborder-radius: var(--border-radius-pill, 16px);\n\tmax-width: fit-content;\n}\n\n.cn-contacts-card__chip-text {\n\tdisplay: flex;\n\tflex-direction: column;\n\tmin-width: 0;\n}\n\n.cn-contacts-card__chip-name {\n\tfont-size: 13px;\n\tfont-weight: 500;\n\twhite-space: nowrap;\n\toverflow: hidden;\n\ttext-overflow