efault: '/index.php/apps/spreed' },\n\t},\n\n\tdata() {\n\t\treturn {\n\t\t\trooms: [],\n\t\t\tloading: false,\n\t\t\terror: '',\n\t\t\tdegraded: '',\n\t\t\tpickerOpen: false,\n\t\t\tcreateOpen: false,\n\t\t}\n\t},\n\n\twatch: {\n\t\tobjectId: { immediate: true, handler(id) { if (id) { this.fetchRooms() } } },\n\t\tregister() { this.fetchRooms() },\n\t\tschema() { this.fetchRooms() },\n\t},\n\n\tmethods: {\n\t\tt,\n\n\t\tbaseUrl() {\n\t\t\treturn `${this.apiBase}/objects/${this.register}/${this.schema}/${this.objectId}/${this.integrationId}`\n\t\t},\n\n\t\troomKey(room) {\n\t\t\treturn room.roomToken ?? room.id ?? room.token ?? room.reference ?? ''\n\t\t},\n\n\t\troomTitle(room) {\n\t\t\tconst raw = room.roomName ?? room.title ?? room.displayName ?? room.name ?? this.roomKey(room)\n\t\t\treturn stripMarker(raw) || String(this.roomKey(room))\n\t\t},\n\n\t\troomUrl(room) {\n\t\t\tif (room.url) {\n\t\t\t\treturn room.url\n\t\t\t}\n\t\t\tconst token = room.roomToken ?? room.token ?? room.id ?? ''\n\t\t\treturn token ? `/index.php/call/${token}` : this.talkAppUrl\n\t\t},\n\n\t\thasUnread(room) {\n\t\t\tconst count = Number(room.unreadMessages ?? room.unread ?? 0)\n\t\t\treturn Number.isFinite(count) && count > 0\n\t\t},\n\n\t\tformatUnread(room) {\n\t\t\tconst count = Number(room.unreadMessages ?? room.unread ?? 0)\n\t\t\tif (!Number.isFinite(count) || count <= 0) {\n\t\t\t\treturn ''\n\t\t\t}\n\t\t\treturn count > 99 ? '99+' : String(count)\n\t\t},\n\n\t\tunreadAriaLabel(room) {\n\t\t\tconst count = Number(room.unreadMessages ?? room.unread ?? 0)\n\t\t\treturn t('nextcloud-vue', '{n} unread', { n: count })\n\t\t},\n\n\t\t/**\n\t\t * Last-message preview line. Falls back to a participant-count\n\t\t * summary so the subname is never empty in NC-Talk style.\n\t\t *\n\t\t * @param {object} room Conversation row.\n\t\t * @return {string} Preview or participant summary.\n\t\t */\n\t\troomSubname(room) {\n\t\t\tconst preview = this.roomPreview(room)\n\t\t\tif (preview) {\n\t\t\t\treturn preview\n\t\t\t}\n\t\t\tconst participants = Number(room.participantCount ?? room.numParticipants ?? 0)\n\t\t\tif (Number.isFinite(participants) && participants > 0) {\n\t\t\t\treturn t('nextcloud-vue', '{n} participants', { n: participants })\n\t\t\t}\n\t\t\treturn ''\n\t\t},\n\n\t\troomPreview(room) {\n\t\t\tlet msg = room.lastMessage\n\t\t\t// The provider may hand us the message as a JSON string; parse it\n\t\t\t// so we never render a raw `{\"message\":...}` blob in the preview.\n\t\t\tif (typeof msg === 'string') {\n\t\t\t\tconst trimmed = msg.trim()\n\t\t\t\tif (trimmed.charAt(0) === '{' || trimmed.charAt(0) === '[') {\n\t\t\t\t\ttry {\n\t\t\t\t\t\tmsg = JSON.parse(trimmed)\n\t\t\t\t\t} catch (e) {\n\t\t\t\t\t\treturn this.cleanPreview(trimmed)\n\t\t\t\t\t}\n\t\t\t\t} else {\n\t\t\t\t\treturn this.cleanPreview(msg)\n\t\t\t\t}\n\t\t\t}\n\t\t\tif (msg && typeof msg === 'object') {\n\t\t\t\t// Talk system messages carry a snake_case key (e.g. `user_added`)\n\t\t\t\t// in `systemMessage`/`message` plus rich `parameters`. Humanise\n\t\t\t\t// them instead of dumping the placeholder/JSON.\n\t\t\t\tconst isSystem = (typeof msg.systemMessage === 'string' && msg.systemMessage !== '')\n\t\t\t\t\t|| msg.messageType === 'system'\n\t\t\t\tconst raw = msg.message ?? msg.text ?? ''\n\t\t\t\tif (isSystem) {\n\t\t\t\t\treturn this.humaniseSystemMessage(msg)\n\t\t\t\t}\n\t\t\t\treturn this.cleanPreview(typeof raw === 'string' ? raw : '')\n\t\t\t}\n\t\t\treturn this.cleanPreview(room.lastMessageText ?? room.preview ?? '')\n\t\t},\n\n\t\t/**\n\t\t * Turn a Talk system message into readable text. Substitutes rich\n\t\t * `{placeholder}` parameters with their display name; falls back to a\n\t\t * title-cased version of the snake_case key (e.g. `user_added` →\n\t\t * \"User added\").\n\t\t *\n\t\t * @param {object} msg The last-message object.\n\t\t * @return {string} Human-readable line.\n\t\t */\n\t\thumaniseSystemMessage(msg) {\n\t\t\tconst key = (typeof msg.systemMe